const store = this.getWorkflowStaticData('global');
if (!store.blacklist) store.blacklist = {};

const http = async (o) => await this.helpers.httpRequest(Object.assign({ timeout: 30000 }, o));

const BOT = '8366696724:AAHROcjGoQEn9BziD-sYdAu3ZuaolwtkgLE';
const CHAT = '523002062';
const NL = String.fromCharCode(10);
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

async function notify(text) {
  try {
    await http({ method: 'POST', url: 'https://api.telegram.org/bot' + BOT + '/sendMessage', json: true, body: { chat_id: CHAT, text } });
  } catch (e) {}
}

const prev = {
  riskCodes: Array.isArray(store.blacklist.riskCodes) ? store.blacklist.riskCodes.slice() : null,
  riskUpdatedAt: store.blacklist.riskUpdatedAt || null,
};

// ===== Naver Finance 관리종목 (1차 소스 - 안정적) =====
async function fetchNaverAdminStocks() {
  const codes = new Set();
  const urls = [
    'https://finance.naver.com/sise/management.naver',
    'https://finance.naver.com/sise/management.naver?sosok=0',
    'https://finance.naver.com/sise/management.naver?sosok=1',
  ];
  for (const url of urls) {
    try {
      const raw = await http({
        method: 'GET',
        url,
        headers: {
          'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36',
          'Accept-Language': 'ko-KR,ko;q=0.9,en;q=0.8',
          'Referer': 'https://finance.naver.com/',
        },
        json: false,
      });
      const text = Buffer.isBuffer(raw) ? raw.toString('utf8') : String(raw || '');
      for (const m of text.matchAll(/code=(\d{6})/g)) codes.add(m[1]);
      await sleep(200);
    } catch (e) {}
  }
  return [...codes];
}

// ===== KRX 거래소 데이터 (2차 소스 - best-effort) =====
// FIX: json: false 로 변경 — json: true 는 form-encoded body를 JSON 직렬화해 400 유발
const KRX_URL = 'https://data.krx.co.kr/comm/bldAttendant/getJsonData.cmd';
const KRX_HEADERS = {
  'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8',
  'Accept': 'application/json, text/javascript, */*; q=0.01',
  'Accept-Language': 'ko-KR,ko;q=0.9,en-US;q=0.8,en;q=0.7',
  'Origin': 'https://data.krx.co.kr',
  'Referer': 'https://data.krx.co.kr/contents/MDC/MDI/mdiLoader/index.cmd?menuId=MDC02021201',
  'X-Requested-With': 'XMLHttpRequest',
  'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36',
};

const KRX_BLDS = [
  'dbms/MDC/STAT/issue/MDCSTAT21201', // 거래정지
  'dbms/MDC/STAT/issue/MDCSTAT21401', // 관리종목
  'dbms/MDC/STAT/issue/MDCSTAT21701', // 투자주의환기(코)
  'dbms/MDC/STAT/issue/MDCSTAT23701', // 정리매매
  'dbms/MDC/STAT/issue/MDCSTAT22801', // 투자주의
  'dbms/MDC/STAT/issue/MDCSTAT23101', // 투자경고
  'dbms/MDC/STAT/issue/MDCSTAT23401', // 투자위험
];

async function fetchKrxCodes(bld) {
  const body = 'bld=' + encodeURIComponent(bld) + '&locale=ko_KR&mktId=ALL&csvxls_isNo=true';
  for (let attempt = 1; attempt <= 2; attempt++) {
    try {
      const raw = await http({
        method: 'POST',
        url: KRX_URL,
        headers: KRX_HEADERS,
        body,
        json: false,  // FIX: form-encoded body를 그대로 전송 (json:true는 body를 JSON 직렬화해 400 유발)
      });
      const res = typeof raw === 'string' ? JSON.parse(raw) : (Buffer.isBuffer(raw) ? JSON.parse(raw.toString('utf8')) : raw); // FIX W-5
      const rows = (res && (res.output || res.OutBlock_1 || [])) || [];
      return rows.map(r => String(r && r.ISU_CD || '').trim()).filter(c => /^\d{6}$/.test(c));
    } catch (e) {
      if (attempt < 2) await sleep(3000);
    }
  }
  return null; // null = 실패 ([] = 성공이나 0건과 구분)
}

async function fetchKrxAllCodes() {
  const codes = new Set();
  const sourceCounts = {};
  let anySuccess = false;
  for (const bld of KRX_BLDS) {
    const list = await fetchKrxCodes(bld);
    const key = bld.split('/').pop();
    if (list !== null) {
      sourceCounts[key] = list.length;
      for (const c of list) codes.add(c);
      anySuccess = true;
    } else {
      sourceCounts[key] = -1;
    }
  }
  return { codes, sourceCounts, anySuccess };
}

// ===== KIND 실질심사법인 (best-effort) =====
async function fetchKindCodes() {
  try {
    const formData = [
      'method=searchDelistRealInvstg', 'forward=delistRealInvstg_down',
      'pageIndex=1', 'currentPageSize=3000',
      'mktTpCd=', 'progrsDelistYn=', 'fromDate=', 'toDate=',
    ].join('&');
    const raw = await http({
      method: 'POST',
      url: 'https://kind.krx.co.kr/corpgeneral/delistRealInvstg.do',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Origin': 'https://kind.krx.co.kr',
        'Referer': 'https://kind.krx.co.kr/corpgeneral/delistRealInvstg.do?method=searchDelistRealInvstgMain',
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36',
      },
      body: formData,
      json: false,
    });
    const text = Buffer.isBuffer(raw) ? raw.toString('latin1') : String(raw || '');
    const set = new Set();
    for (const m of text.matchAll(/mso-number-format:'@'[^>]*>\s*(\d{6})\s*<\/td>/g)) set.add(m[1]);
    return [...set];
  } catch (e) {
    return [];
  }
}

// ===== 메인 실행 =====
try {
  const allCodes = new Set();
  const sourceCounts = {};

  // 1. Naver 관리종목 (1차 소스)
  const naverCodes = await fetchNaverAdminStocks();
  sourceCounts['Naver'] = naverCodes.length;
  for (const c of naverCodes) allCodes.add(c);

  // 2. KRX (2차 소스 - best-effort)
  const krxResult = await fetchKrxAllCodes();
  Object.assign(sourceCounts, krxResult.sourceCounts);
  for (const c of krxResult.codes) allCodes.add(c);

  // 3. KIND (best-effort)
  const kindCodes = await fetchKindCodes();
  sourceCounts['KIND'] = kindCodes.length;
  for (const c of kindCodes) allCodes.add(c);

  // 수집 결과 0건이고 캐시가 있으면 캐시 유지
  if (allCodes.size === 0 && prev.riskCodes && prev.riskCodes.length > 0) {
    await notify('⚠️ [리스크 블랙리스트] 신규 0건 — 기존 캐시 유지' + NL +
      '기존: ' + prev.riskCodes.length + '개 / 마지막 갱신: ' + (prev.riskUpdatedAt || '없음'));
    return [{ json: { ok: true, keptCache: true, riskCodesCount: prev.riskCodes.length, riskUpdatedAt: prev.riskUpdatedAt } }];
  }

  store.blacklist.riskCodes = [...allCodes].sort();
  store.blacklist.riskUpdatedAt = new Date().toISOString();
  store.blacklist.riskSourceCounts = sourceCounts;
  store.blacklist.riskSource = 'Naver+KRX+KIND';
  delete store.blacklist.riskLastError;

  const krxStatus = krxResult.anySuccess ? '✅' : '❌(캐시없이 진행)';
  await notify('✅ [리스크 블랙리스트 갱신 성공]' + NL +
    '총 ' + store.blacklist.riskCodes.length + '개 종목' + NL +
    '네이버: ' + naverCodes.length + '개 | KRX: ' + krxStatus + ' | KIND: ' + kindCodes.length + '개' + NL +
    '갱신: ' + store.blacklist.riskUpdatedAt);

  return [{
    json: {
      ok: true,
      riskCodesCount: store.blacklist.riskCodes.length,
      riskSourceCounts: sourceCounts,
      riskUpdatedAt: store.blacklist.riskUpdatedAt,
      krxSuccess: krxResult.anySuccess,
    },
  }];

} catch (e) {
  const msg = String(e && e.message ? e.message : e);
  // FIX: axios는 e.response.status (statusCode 아님)
  const status = (e && (e.statusCode || (e.response && (e.response.status || e.response.statusCode)))) || null;
  const detail = status ? 'HTTP ' + status + ': ' + msg : msg;

  store.blacklist.riskLastError = { at: new Date().toISOString(), message: detail, status };
  if (prev.riskCodes) store.blacklist.riskCodes = prev.riskCodes;
  if (prev.riskUpdatedAt) store.blacklist.riskUpdatedAt = prev.riskUpdatedAt;

  await notify('🚨 [리스크 블랙리스트 갱신 실패]' + NL + detail + NL + '(캐시: ' + (store.blacklist.riskUpdatedAt || '없음') + ')');
  return [{ json: { ok: false, error: detail, status, riskUpdatedAt: store.blacklist.riskUpdatedAt || null } }];
}

const store = this.getWorkflowStaticData('global');
if (!store.blacklist) store.blacklist = {};

const http = async (o) =>
  await this.helpers.httpRequest(
    Object.assign(
      {
        timeout: 30000,
      },
      o
    )
  );

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function toText(raw) {
  if (Buffer.isBuffer(raw)) return raw.toString('utf8');
  return String(raw ?? '');
}

async function fetchText(url, referer) {
  const raw = await http({
    method: 'GET',
    url,
    headers: {
      'User-Agent': 'Mozilla/5.0',
      Referer: referer || 'https://finance.naver.com/',
      'Accept-Language': 'ko-KR,ko;q=0.9,en;q=0.8',
    },
    json: false,
  });
  return toText(raw);
}

async function fetchTextRetry(url, referer, tries = 2) {
  let lastErr;
  for (let i = 0; i < tries; i++) {
    try {
      return await fetchText(url, referer);
    } catch (e) {
      lastErr = e;
      await sleep(300 + i * 500);
    }
  }
  throw lastErr;
}

function uniq(arr) {
  return [...new Set(arr)];
}

function extractThemeNos(html) {
  // /sise/sise_group_detail.naver?type=theme&no=584
  return uniq([...html.matchAll(/sise_group_detail\.naver\?type=theme&no=(\d+)/g)].map((m) => m[1]));
}

function extractCodes(html) {
  // /item/main.naver?code=005930
  return uniq([...html.matchAll(/code=(\d{6})/g)].map((m) => m[1]));
}

async function mapLimit(list, limit, worker) {
  const results = [];
  const errors = [];
  let idx = 0;

  const runners = new Array(Math.min(limit, list.length)).fill(0).map(async () => {
    while (idx < list.length) {
      const i = idx++;
      try {
        results[i] = await worker(list[i], i);
      } catch (e) {
        errors.push({ i, item: list[i], message: e?.message || String(e) });
        results[i] = null;
      }
    }
  });

  await Promise.all(runners);
  return { results, errors };
}

// ====== 튜닝 포인트(차단/느림이면 여기만 조절) ======
const MAX_LIST_PAGES = 20;     // 테마 목록 페이지 최대 탐색
const CONCURRENCY = 6;         // 테마 상세 동시 요청 수 (차단되면 3으로 낮추세요)
const DETAIL_SLEEP_MS = 120;   // 상세 요청 사이 아주 짧은 텀(차단 완화)
const LIST_SLEEP_MS = 120;     // 목록 페이지 요청 텀
// =====================================================

const startTs = Date.now();
const baseList = 'https://finance.naver.com/sise/theme.naver';
const listReferer = 'https://finance.naver.com/sise/theme.naver';

// 1) 테마 no 목록 수집
const html1 = await fetchTextRetry(`${baseList}?&page=1`, listReferer, 2);
let themeNos = extractThemeNos(html1);

if (themeNos.length === 0) {
  return [
    {
      json: {
        ok: false,
        reason: 'No theme no found on list page (expected type=theme&no=###)',
        lenUtf8: html1.length,
        snippet: html1.slice(0, 1200),
      },
    },
  ];
}

// 페이지 수 추정
const pagesFound = uniq([...html1.matchAll(/page=(\d+)/g)].map((m) => Number(m[1]) || 1)).filter((n) => n >= 1);
let maxPage = pagesFound.length ? Math.max(...pagesFound) : MAX_LIST_PAGES;
maxPage = Math.min(maxPage, MAX_LIST_PAGES);

const allNos = new Set(themeNos);
let stoppedEarlyAtPage = null;

for (let p = 2; p <= maxPage; p++) {
  await sleep(LIST_SLEEP_MS);
  const html = await fetchTextRetry(`${baseList}?&page=${p}`, listReferer, 2);
  const nos = extractThemeNos(html);

  let added = 0;
  for (const no of nos) {
    if (!allNos.has(no)) {
      allNos.add(no);
      added++;
    }
  }

  if (added === 0 && p >= 3) {
    stoppedEarlyAtPage = p;
    break;
  }
}

themeNos = [...allNos].sort((a, b) => Number(a) - Number(b));

// 2) 테마 상세에서 종목코드 수집(동시처리)
const codeSet = new Set();
const detailErrors = [];

const detailReferer = 'https://finance.naver.com/sise/theme.naver';
const { errors } = await mapLimit(themeNos, CONCURRENCY, async (no) => {
  await sleep(DETAIL_SLEEP_MS);
  const url = `https://finance.naver.com/sise/sise_group_detail.naver?type=theme&no=${no}`;
  const html = await fetchTextRetry(url, detailReferer, 2);
  const codes = extractCodes(html);
  for (const c of codes) codeSet.add(c);
  return { no, codesCount: codes.length };
});

if (errors.length) detailErrors.push(...errors);

// 3) 저장 + 리턴
const themeCodes = [...codeSet].sort();
const prevThemeCodes = Array.isArray(store.blacklist.themeCodes) ? store.blacklist.themeCodes : [];
const BOT_T = '8366696724:AAHROcjGoQEn9BziD-sYdAu3ZuaolwtkgLE';
const CHAT_T = '523002062';
const NL_T = String.fromCharCode(10);
// FIX C-4: 0건 수집 시 캐시 보존 (Risk Updater와 동일 패턴)
if (themeCodes.length === 0 && prevThemeCodes.length > 0) {
  try { await http({ method: 'POST', url: 'https://api.telegram.org/bot' + BOT_T + '/sendMessage', json: true, body: { chat_id: CHAT_T, text: '⚠️ [테마 블랙리스트] 신규 0건 — 기존 캐시 유지' + NL_T + '기존: ' + prevThemeCodes.length + '개' } }); } catch(e) {}
  return [{ json: { ok: true, keptCache: true, themeCodesCount: prevThemeCodes.length } }];
}
store.blacklist.themeCodes = themeCodes;
store.blacklist.themeUpdatedAt = new Date().toISOString();
store.blacklist.themeNosCount = themeNos.length;
store.blacklist.themeSource = 'naver:sise_group_detail';
store.blacklist.themeFetchStats = {
  stoppedEarlyAtPage,
  maxPageTried: maxPage,
  concurrency: CONCURRENCY,
  detailErrors: detailErrors.length,
  ms: Date.now() - startTs,
};

// FIX W-6: 성공 알림
try { await http({ method: 'POST', url: 'https://api.telegram.org/bot' + BOT_T + '/sendMessage', json: true, body: { chat_id: CHAT_T, text: '✅ [테마 블랙리스트 갱신 성공]' + NL_T + '총 ' + themeCodes.length + '개 종목 / 테마 ' + themeNos.length + '개' + NL_T + '갱신: ' + store.blacklist.themeUpdatedAt } }); } catch(e) {}
return [
  {
    json: {
      ok: true,
      done: true,
      themeNosCount: themeNos.length,
      themeCodesCount: themeCodes.length,
      themeUpdatedAt: store.blacklist.themeUpdatedAt,
      stats: store.blacklist.themeFetchStats,
      sampleCodes: themeCodes.slice(0, 20),
      detailErrors: detailErrors.slice(0, 10),
    },
  },
];

const run = async function () {
  const BOT = '8366696724:AAHROcjGoQEn9BziD-sYdAu3ZuaolwtkgLE';
  const CHAT = '523002062';
  const http = async (o) => await this.helpers.httpRequest(Object.assign({ timeout: 30000 }, o));

  const now = new Date();
  const kst = new Date(now.getTime() + 9*60*60*1000);
  const today = `${kst.getUTCFullYear()}-${String(kst.getUTCMonth()+1).padStart(2,'0')}-${String(kst.getUTCDate()).padStart(2,'0')}`;
  const timeKst = `${String(kst.getUTCHours()).padStart(2,'0')}:${String(kst.getUTCMinutes()).padStart(2,'0')}`;
  const HOLIDAYS_2026 = ['2026-01-01','2026-02-16','2026-02-17','2026-02-18','2026-03-01','2026-03-02','2026-05-05','2026-05-24','2026-05-25','2026-06-03','2026-06-06','2026-08-15','2026-08-17','2026-09-24','2026-09-25','2026-09-26','2026-10-03','2026-10-05','2026-10-09','2026-12-25'];
  if (HOLIDAYS_2026.includes(today)) {
    return [{ json: { skipped: true, reason: 'Holiday (KRX closed)', today, timeKst } }];
  }

  const store = this.getWorkflowStaticData('global');
  if (!store.healthcheck) store.healthcheck = {};
  if (store.healthcheck.lastSentDate === today) {
    return [{ json: { skipped: true, reason: 'Already sent today', today, timeKst } }];
  }

  // (선택) KRX 데이터 접근 가능 여부를 같이 점검  // (KRX live probe disabled) - KRX 차단/불안정 시 400을 유발할 수 있어 live 호출을 하지 않습니다.
  // 대신, 오늘자 KRX 유니버스 캐시/서킷 상태만 보고합니다.  // (KRX live probe disabled) - KRX 차단/불안정 시 400을 유발할 수 있어 live 호출을 하지 않습니다.
  // 대신, 오늘자 KRX 유니버스 캐시/서킷 상태만 보고합니다.
  let krxStatus = '미확인';
  let krxCount = 0;
  try {
    const store = this.getWorkflowStaticData('global');
    const trdDd = `${kst.getUTCFullYear()}${String(kst.getUTCMonth()+1).padStart(2,'0')}${String(kst.getUTCDate()).padStart(2,'0')}`;
    const cache = store && store.krxUniverseCache;
    const st = store && store.krxState;

    const nowMs = now.getTime();
    const circuitUntil = st && st.circuitUntil ? new Date(st.circuitUntil).getTime() : 0;
    const circuitActive = !!(circuitUntil && circuitUntil > nowMs && st && st.circuitDate === today);

    if (circuitActive) {
      krxStatus = `서킷 활성(circuitUntil=${st.circuitUntil})`;
    } else if (cache && cache.trdDd === trdDd && Array.isArray(cache.rows) && cache.rows.length) {
      krxCount = cache.rows.length;
      krxStatus = `캐시 OK (${krxCount}개)`;
    } else if (cache && Array.isArray(cache.rows) && cache.rows.length) {
      krxCount = cache.rows.length;
      krxStatus = `캐시(최근) ${krxCount}개 (trdDd=${cache.trdDd || 'unknown'})`;
    } else {
      krxStatus = '캐시 없음 (live probe 비활성)';
    }
  } catch (e) {
    krxStatus = '상태확인 실패: ' + String(e && e.message ? e.message : e);
  }

  const msg = `✅ [헬스체크] Autostock 스케줄러 정상\n- KST: ${today} ${timeKst}\n- KRX: ${krxStatus}`;

  try {
    await http({
      method: 'POST',
      url: 'https://api.telegram.org/bot' + BOT + '/sendMessage',
      json: true,
      body: { chat_id: CHAT, text: msg }
    });
  } catch (e) {
    return [{ json: { ok: false, error: String(e && e.message ? e.message : e), today, timeKst, krxStatus, krxCount } }];
  }

  store.healthcheck.lastSentDate = today;
  store.healthcheck.lastSentAt = now.toISOString();
  store.healthcheck.lastKrxStatus = krxStatus;
  store.healthcheck.lastKrxCount = krxCount;

  return [{ json: { ok: true, today, timeKst, krxStatus, krxCount } }];
};
return run();

const run = async function () {
  const BOT = '8366696724:AAHROcjGoQEn9BziD-sYdAu3ZuaolwtkgLE';
  const CHAT = '523002062';
  const MIN_INTRADAY_TURNOVER = 3000000000; // 30억 KRW
  const MIN_PRICE = 1000;                   // 최소 주가 (프레임워크 — KRX API 필터)
  const ETF_EXCLUDE_KEYWORDS = [];          // 제외 ETF 키워드 (초기화 — 새 조건에서 재정의)
  const HOLIDAYS = ['2025-01-01','2025-01-28','2025-01-29','2025-01-30','2025-03-01','2025-03-03','2025-05-05','2025-05-06','2025-06-06','2025-08-15','2025-10-03','2025-10-06','2025-10-07','2025-10-08','2025-10-09','2025-12-25','2026-01-01','2026-02-16','2026-02-17','2026-02-18','2026-03-01','2026-03-02','2026-05-05','2026-05-24','2026-05-25','2026-06-03','2026-06-06','2026-07-17','2026-08-15','2026-08-17','2026-09-24','2026-09-25','2026-09-26','2026-10-03','2026-10-05','2026-10-09','2026-12-25'];
  const DUPLICATE_WINDOW_MINUTES = 480;
