  // [DATA-FIX] 예상 전거래일 계산 — 데이터 신선도 검증용 (2026-06-03)
  const getPrevTradingDay = (todayStr) => {
    let d = new Date(todayStr + 'T00:00:00Z');
    for (let i = 0; i < 10; i++) {
      d = new Date(d.getTime() - 86400000);
