    }

    // ── [MACRO-A] 매크로 지표: 나스닥 + VIX + S&P500선물 — KOSPI/KOSDAQ 동일 적용 (2026-05-17) ──
    let nasdaqChg = null, vixLevel = null, esFutChg = null, macroAdj = 0;
