  if (!store.weeklyRecommendations[today]) store.weeklyRecommendations[today] = [];

  // ===== [SCAN-LOG] 상세 스캔 로그 초기화 (2026-05-17) =====
  if (!store.scanLog) store.scanLog = [];
  const _log = {
    runId: requestId,
    date: today, startKst: timeStrNow, startAt: now.toISOString(),
